function icon(string $name, string $cls = ''): string
{
    if (!in_array($name, ICON_NAMES, true)) {
        $name = 'dot';
    }
    return '<svg class="ic ic-' . $name . ($cls !== '' ? ' ' . htmlspecialchars($cls, ENT_QUOTES) : '') . '" aria-hidden="true" focusable="false"><use href="#i-' . $name . '"/></svg>';
}
/** Escape teks lalu ganti token :nama-ikon: dengan SVG ikon. */
function eic(string $s): string
{
    return preg_replace_callback('/:([a-z][a-z0-9-]*):/', fn ($m) => in_array($m[1], ICON_NAMES, true) ? icon($m[1]) : $m[0], htmlspecialchars($s, ENT_QUOTES, 'UTF-8'));
}
/** Ikon notifikasi: nama ikon baru, atau simbol lama yang tersimpan di database. */
function notif_icon(string $v): string
{
    static $legacy = ['☑' => 'square-check', '◔' => 'hourglass', '↺' => 'undo', '✳' => 'star', '✓' => 'check', '✕' => 'xmark', '?' => 'question', '⚑' => 'flag', '▢' => 'comment', '💬' => 'chat', '♙' => 'user', '♡' => 'heart-o', '⟳' => 'retweet', '⚔' => 'users'];
    $n = in_array($v, ICON_NAMES, true) ? $v : ($legacy[$v] ?? '');
    return $n !== '' ? icon($n) : icon('bell');
}
